/**
 * Typed HCL value model and writer functions.
 *
 * Provides a discriminated-union AST for HCL values and pure functions
 * that render them to syntactically valid HCL text. Unlike the simpler
 * `file-assembler.ts` printer that works on untyped `unknown` values,
 * this module gives callers full control over the output format (blocks
 * vs maps, expressions vs literals, etc.).
 *
 * @module codegen/hcl-writer
 * @generated by code-generator (TASK-TRANS-006)
 */

// ---------------------------------------------------------------------------
// HCL value AST
// ---------------------------------------------------------------------------

export interface HclLiteral {
  readonly kind: 'literal';
  readonly value: string | number | boolean | null;
}

export interface HclExpr {
  readonly kind: 'expr';
  readonly expr: string;
}

export interface HclMapEntry {
  readonly key: string;
  readonly value: HclValue;
}

export interface HclMap {
  readonly kind: 'map';
  readonly entries: readonly HclMapEntry[];
}

export interface HclBlock {
  readonly kind: 'block';
  readonly body: readonly HclMapEntry[];
}

export interface HclList {
  readonly kind: 'list';
  readonly items: readonly HclValue[];
}

export interface HclBlocks {
  readonly kind: 'blocks';
  readonly blocks: readonly HclMapEntry[];
}

export type HclValue =
  | HclLiteral
  | HclExpr
  | HclMap
  | HclBlock
  | HclList
  | HclBlocks;

// ---------------------------------------------------------------------------
// Constructor helpers
// ---------------------------------------------------------------------------

/** Create an HCL literal value. */
export function literal(value: string | number | boolean | null): HclLiteral {
  return { kind: 'literal', value };
}

/** Create an HCL expression (rendered without quotes). */
export function expr(raw: string): HclExpr {
  return { kind: 'expr', expr: raw };
}

/**
 * Create an HCL map from a plain object.
 * Entries are ordered by insertion (Object.keys order).
 */
export function hclMap(entries: Record<string, HclValue>): HclMap {
  return {
    kind: 'map',
    entries: Object.keys(entries).map((k) => ({ key: k, value: entries[k]! })),
  };
}

/**
 * Create an HCL block from a plain object.
 * Blocks render scalar attributes with `=` but nested blocks without `=`.
 */
export function block(body: Record<string, HclValue>): HclBlock {
  return {
    kind: 'block',
    body: Object.keys(body).map((k) => ({ key: k, value: body[k]! })),
  };
}

/** Create an HCL list. */
export function list(items: readonly HclValue[]): HclList {
  return { kind: 'list', items };
}

// ---------------------------------------------------------------------------
// String escaping
// ---------------------------------------------------------------------------

function escapeHcl(s: string): string {
  return s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

// ---------------------------------------------------------------------------
// Value writer
// ---------------------------------------------------------------------------

/**
 * Renders an {@link HclValue} to a string at the given indentation depth.
 *
 * @param value  - The HCL value to render.
 * @param indent - Current indentation depth (number of 2-space levels).
 * @returns The rendered HCL text fragment.
 */
export function writeHclValue(value: HclValue, indent: number): string {
  const pad = '  '.repeat(indent);
  const inner = '  '.repeat(indent + 1);

  switch (value.kind) {
    case 'literal': {
      const v = value.value;
      if (v === null) return 'null';
      if (typeof v === 'boolean') return v ? 'true' : 'false';
      if (typeof v === 'number') return String(v);
      return `"${escapeHcl(v)}"`;
    }

    case 'expr':
      return value.expr;

    case 'map': {
      if (value.entries.length === 0) return '{}';
      const lines = value.entries.map(
        (e) => `${inner}${e.key} = ${writeHclValue(e.value, indent + 1)}`,
      );
      return `{\n${lines.join('\n')}\n${pad}}`;
    }

    case 'block': {
      if (value.body.length === 0) return '{}';
      const lines = value.body.map((e) => {
        // Nested blocks render without `=`; scalars/maps/lists use `=`
        if (e.value.kind === 'block' || e.value.kind === 'blocks') {
          return `${inner}${e.key} ${writeHclValue(e.value, indent + 1)}`;
        }
        return `${inner}${e.key} = ${writeHclValue(e.value, indent + 1)}`;
      });
      return `{\n${lines.join('\n')}\n${pad}}`;
    }

    case 'list': {
      if (value.items.length === 0) return '[]';
      const lines = value.items.map(
        (item) => `${inner}${writeHclValue(item, indent + 1)}`,
      );
      return `[\n${lines.join(',\n')},\n${pad}]`;
    }

    case 'blocks': {
      // Each entry becomes a labeled sub-block: `key { ... }`
      return value.blocks
        .map((e) => {
          const bodyStr = writeHclValue(e.value, indent);
          return `${e.key} ${bodyStr}`;
        })
        .join(`\n${pad}`);
    }

    default: {
      // NO-THROW: unknown value kind → inline comment fallback
      const unknown = value as { kind?: string };
      return `"/* unknown HCL value kind: ${unknown.kind ?? 'undefined'} */"`;
    }
  }
}

// ---------------------------------------------------------------------------
// Top-level block writers
// ---------------------------------------------------------------------------

export interface BlockWriteOptions {
  /** Optional comment line above the block. */
  readonly comment?: string;
  /** Sort body entries by key (default false). */
  readonly sortKeys?: boolean;
}

/**
 * Renders a `resource "type" "name" { ... }` block.
 */
export function writeResourceBlock(
  type: string,
  name: string,
  body: readonly HclMapEntry[],
  options?: BlockWriteOptions,
): string {
  const sorted = options?.sortKeys
    ? [...body].sort((a, b) => a.key.localeCompare(b.key))
    : body;

  const lines: string[] = [];
  if (options?.comment) {
    lines.push(`# ${options.comment}`);
  }
  lines.push(`resource "${type}" "${name}" {`);
  for (const entry of sorted) {
    if (entry.value.kind === 'blocks') {
      // Expand repeated sub-blocks: each gets its own `key { ... }` line
      for (const sub of entry.value.blocks) {
        lines.push(`  ${sub.key} ${writeHclValue(sub.value, 1)}`);
      }
    } else if (entry.value.kind === 'block') {
      lines.push(`  ${entry.key} ${writeHclValue(entry.value, 1)}`);
    } else {
      lines.push(`  ${entry.key} = ${writeHclValue(entry.value, 1)}`);
    }
  }
  lines.push('}');
  return lines.join('\n');
}

