/**
 * Renders a `variable "name" { ... }` block.
 */
export function writeVariableBlock(
  name: string,
  props: {
    readonly description?: string;
    readonly type?: string;
    readonly defaultValue?: HclValue;
    readonly sensitive?: boolean;
  },
): string {
  const lines: string[] = [];
  lines.push(`variable "${name}" {`);
  if (props.description !== undefined) {
    lines.push(`  description = "${escapeHcl(props.description)}"`);
  }
  if (props.type !== undefined) {
    lines.push(`  type        = ${props.type}`);
  }
  if (props.defaultValue !== undefined) {
    lines.push(`  default     = ${writeHclValue(props.defaultValue, 1)}`);
  }
  if (props.sensitive === true) {
    lines.push('  sensitive   = true');
  }
  lines.push('}');
  return lines.join('\n');
}

/**
 * Renders an `output "name" { ... }` block.
 */
export function writeOutputBlock(
  name: string,
  props: {
    readonly value: HclValue;
    readonly description?: string;
    readonly sensitive?: boolean;
  },
): string {
  const lines: string[] = [];
  lines.push(`output "${name}" {`);
  if (props.description !== undefined) {
    lines.push(`  description = "${escapeHcl(props.description)}"`);
  }
  lines.push(`  value       = ${writeHclValue(props.value, 1)}`);
  if (props.sensitive === true) {
    lines.push('  sensitive   = true');
  }
  lines.push('}');
  return lines.join('\n');
}
